//! Typed MCP `inputSchema`s for the `CoreTools` handlers (PSP-03 / plan B2).
//!
//! Each struct documents the JSON object one handler reads. The handlers keep
//! parsing their `serde_json::Value` themselves — tool names, argument names
//! and call semantics are the public contract and do not change — so these
//! types only describe the wire shape. They are attached to the handlers
//! through rmcp's `#[tool(input_schema = ...)]` and generated by the same
//! schemars generator rmcp uses for `Parameters<T>` tools (JSON Schema
//! 2020-12, root `type: "object"`, top-level title/description stripped).
//!
//! A field is `required` only when the handler refuses the call without it;
//! defaults and accepted aliases are spelled out in the field docs. A field
//! the handler deserializes with serde into a non-`Option` `#[serde(default)]`
//! type keeps that type here, so the schema never admits a `null` the
//! handler would reject.
//!
//! Output schemas (the other half of B2) are deferred to B4: many handlers
//! return a JSON document, but as text content. Declaring an
//! `outputSchema` obliges the server to send `structuredContent`, which
//! changes the result envelope, so it lands with each B4 group additively.

use std::collections::BTreeMap;
use std::sync::{Arc, OnceLock};
use susi_vendor_mcp_server as rmcp;

use super::CoreTools;

use rmcp::model::JsonObject;
use rmcp::schemars::JsonSchema;

/// Marker key on a schema whose arguments are forwarded unchanged to a
/// backing server (external `server:tool` proxies, Wasm reflexes). Built-in
/// tools never carry it.
pub const PASSTHROUGH_KEY: &str = "x-susi-passthrough";

/// Schema for a tool that reads a typed argument object.
///
/// A type whose schema is not a root object (a build bug, caught by the
/// schema tests) yields an open `{type: object}` schema rather than a
/// panic; the `tools/list` invariant test rejects that shape.
pub fn typed<T: JsonSchema + std::any::Any>() -> Arc<JsonObject> {
    rmcp::handler::server::common::schema_for_input::<T>().unwrap_or_else(|_| {
        let mut open = JsonObject::new();
        open.insert("type".into(), serde_json::json!("object"));
        Arc::new(open)
    })
}

/// Explicit "takes no arguments": an empty `properties` object that admits
/// no additional properties. The handler ignores whatever it is sent.
pub fn no_args() -> Arc<JsonObject> {
    let mut object = JsonObject::new();
    object.insert("type".into(), serde_json::json!("object"));
    object.insert("properties".into(), serde_json::json!({}));
    object.insert("additionalProperties".into(), serde_json::json!(false));
    Arc::new(object)
}

/// Schema for a dynamically discovered tool whose arguments SUSI forwards
/// unchanged (an external MCP server's `server:tool`, a Wasm reflex). The
/// backing server's own `inputSchema` is dropped at discovery
/// (`susi_vendor_mcp::list_tools_blocking` returns only name and
/// description), so the shape is declared as passthrough instead of being
/// guessed. This is a recorded deviation from the B2 invariant for dynamic
/// proxies only; built-in tools never use it.
pub fn passthrough() -> Arc<JsonObject> {
    let mut object = JsonObject::new();
    object.insert("type".into(), serde_json::json!("object"));
    object.insert("additionalProperties".into(), serde_json::json!(true));
    object.insert(PASSTHROUGH_KEY.into(), serde_json::json!(true));
    object.insert(
        "description".into(),
        serde_json::json!("Arguments are forwarded unchanged to the backing MCP server or reflex."),
    );
    Arc::new(object)
}

